// /frontend-react/src/components/AppointmentFlow.js

import React, { useState } from 'react';
import HeaderBar from './HeaderBar';

const FlowButton = ({ label, emoji, isBlinking, onClick, isEasyMode, primaryColor = '#007bff' }) => (
    <button 
        onClick={onClick}
        style={{
            // Styling for flexible layout (3 items in a row for transport needs)
            padding: '20px 10px', 
            margin: '10px 5px', 
            border: `4px solid ${isBlinking ? primaryColor : '#ccc'}`,
            backgroundColor: isBlinking ? '#ffffcc' : 'white',
            fontWeight: 'bold',
            fontSize: isEasyMode ? '24px' : '18px',
            animation: isBlinking ? 'pulse 1.5s infinite' : 'none',
            cursor: 'pointer',
            transition: 'all 0.3s',
            borderRadius: '10px',
            color: '#333',
            width: '30%', // Allows for 3-4 buttons in a row responsively
            minWidth: '100px',
            boxSizing: 'border-box',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
        }}
    >
        <span role="img" aria-label={label} style={{fontSize: isEasyMode ? '50px' : '30px', display: 'block', marginBottom: '5px'}}>{emoji}</span>
        {label}
    </button>
);

// /frontend-react/src/components/AppointmentFlow.js (Required Modifications)

function AppointmentFlow({ isEasyMode, appointment, goToTransportStatus, goToMedicalDashboard }) {
    // ... existing state ...
    const [transportNeed, setTransportNeed] = useState(null); 
    
    // NEW STATE: Control visibility of the separate input screen
    const [showOtherInput, setShowOtherInput] = useState(false); 
    // NEW STATE: To hold the custom text need
    const [customNeedText, setCustomNeedText] = useState('');

    // ... sendTransportData function remains the same ...

    // --- NEW FUNCTIONS ---
    const handleConfirmOtherNeed = (text) => {
        setCustomNeedText(text); // Save the text
        setTransportNeed('other'); // Ensure 'other' is still the selection key
        setShowOtherInput(false); // Go back to the main flow
    };

    const handleCancelOtherNeed = () => {
        // Clear selection and go back to selection step
        setTransportNeed(null); 
        setShowOtherInput(false); 
    };
    
    // --- MODIFIED BUTTON HANDLER ---
    const handleNeedSelection = (key) => {
        if (key === 'other') {
            setShowOtherInput(true); // Open the new screen
        } else {
            setTransportNeed(key);
        }
    };
    // --------------------------------

    // ... getBlinkingStyle function remains the same ...

    // --- MODIFIED RETURN BLOCK ---
    if (showOtherInput) {
        return (
            <OtherNeedInput 
                isEasyMode={isEasyMode}
                onConfirmNeed={handleConfirmOtherNeed}
                onCancel={handleCancelOtherNeed}
            />
        );
    }
    
    // Standard Appointment Flow rendering below:
    return (
        <div style={{ padding: '0 20px 20px 20px', textAlign: 'center' }}>
            {/* ... Existing header and Step 1/2/4 ... */}
            
            {/* 3. Choose Needs */}
            {/* ... Only show this if NOT in the other input screen ... */}
            {step >= 2 && needsTransport && (
                <div style={{...getBlinkingStyle(2), padding: '20px', borderRadius: '15px'}}>
                    {/* ... (Existing Step 3 content) ... */}
                    <div style={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'center', gap: '5px' }}>
                        {transportOptions.map(option => (
                            <FlowButton
                                key={option.key}
                                label={option.label}
                                emoji={option.emoji}
                                isBlinking={step === 2 && transportNeed !== option.key}
                                isEasyMode={isEasyMode}
                                onClick={() => handleNeedSelection(option.key)} // USE NEW HANDLER
                                primaryColor={option.key === 'other' ? 'purple' : '#1A73E8'}
                            />
                        ))}
                    </div>

                    {/* Display recorded text if available */}
                    {transportNeed === 'other' && customNeedText && (
                        <div style={{marginTop: '15px', padding: '10px', border: '1px dashed green', borderRadius: '5px'}}>
                             <p style={{fontSize: isEasyMode ? '20px' : '14px', margin: 0}}>
                                **Confirmed Need:** {customNeedText}
                             </p>
                        </div>
                    )}
                    
                    {/* ... (Existing Confirm Button) ... */}
                    {transportNeed && (
                        <button onClick={sendTransportData}>Confirm & Book ✅</button>
                    )}
                </div>
            )}
        </div>
    );
}

export default AppointmentFlow;
